<?php
namespace App\Livewire\Admin\Customers; use App\Models\Customer; use Livewire\Component;
class Create extends Component{public string $name='';public string $email='';public string $phone='';public string $address='';public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->hasPermission('customers.create'),403);}public function save(){$d=$this->validate(['name'=>['required','string','max:255'],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:255'],'address'=>['nullable','string','max:1000']]);$customer=Customer::create(['name'=>$d['name'],'contact_info'=>collect($d)->except('name')->filter(fn($v)=>filled($v))->all()]);session()->flash('success','Customer created.');return $this->redirectRoute('admin.customers.show',$customer,navigate:true);}public function render(){return view('livewire.admin.customers.form',['heading'=>'New customer','submitLabel'=>'Create customer'])->layout('components.layouts.admin',['title'=>'New customer']);}}
